import * as crypto from 'crypto';
import { EventEmitter } from 'events';

interface DeviceConfig {
  deviceId: string;
  firmwareVersion: string;
  encryptionKey: Buffer;
  allowedModules: string[];
}

interface StorageEntry {
  iv: Buffer;
  ciphertext: Buffer;
  tag: Buffer;
}

class SecureStorage {
  private store: Map<string, StorageEntry> = new Map();
  private key: Buffer;

  constructor(key: Buffer) {
    this.key = key;
  }

  encrypt(plaintext: string): StorageEntry {
    const iv = crypto.randomBytes(12);
    const cipher = crypto.createCipheriv('aes-256-gcm', this.key, iv);
    const ciphertext = Buffer.concat([cipher.update(plaintext, 'utf8'), cipher.final()]);
    const tag = cipher.getAuthTag();
    return { iv, ciphertext, tag };
  }

  decrypt(entry: StorageEntry): string {
    const decipher = crypto.createDecipheriv('aes-256-gcm', this.key, entry.iv);
    decipher.setAuthTag(entry.tag);
    return decipher.update(entry.ciphertext) + decipher.final('utf8');
  }

  put(key: string, value: string): void {
    this.store.set(key, this.encrypt(value));
  }

  get(key: string): string | null {
    const entry = this.store.get(key);
    if (!entry) return null;
    return this.decrypt(entry);
  }
}

class ModuleRegistry {
  private modules: Map<string, any> = new Map();
  private allowedModules: Set<string>;

  constructor(allowedModules: string[]) {
    this.allowedModules = new Set(allowedModules);
  }

  register(name: string, module: any): void {
    if (this.allowedModules.has(name)) {
      this.modules.set(name, module);
    }
  }

  isAllowed(name: string): boolean {
    return this.allowedModules.has(name);
  }

  getModule(name: string): any | null {
    return this.modules.get(name) || null;
  }
}

class FirmwareController extends EventEmitter {
  private storage: SecureStorage;
  private registry: ModuleRegistry;
  private config: DeviceConfig;

  constructor(config: DeviceConfig) {
    super();
    this.config = config;
    this.storage = new SecureStorage(config.encryptionKey);
    this.registry = new ModuleRegistry(config.allowedModules);
    this.initializeDefaultModules();
  }

  private initializeDefaultModules(): void {
    this.registry.register('sensor', { read: () => ({ temp: 22.5, humidity: 45 }) });
    this.registry.register('actuator', { write: (v: number) => console.log(`Set: ${v}`) });
    this.registry.register('diagnostics', { status: () => 'OK' });
  }

  processCommand(encryptedPayload: StorageEntry): any {
    const rawCommand = this.storage.decrypt(encryptedPayload);
    const command = JSON.parse(rawCommand);
    return this.executeCommand(command);
  }

  private resolveHandler(moduleName: string, methodName: string): Function | null {
    const mod = this.registry.getModule(moduleName);
    if (!mod) return null;
    const handler = mod[methodName];
    if (typeof handler !== 'function') return null;
    return handler;
  }

  private executeCommand(command: { module: string; method: string; args?: any[] }): any {
    const { module: moduleName, method, args = [] } = command;

    if (!this.registry.isAllowed(moduleName)) {
      throw new Error(`Module '${moduleName}' is not in the allowlist`);
    }

    const qualifiedName = `${moduleName}.${method}`;
    this.emit('command:before', qualifiedName);

    const handler = this.resolveHandler(moduleName, method);
    if (!handler) {
      throw new Error(`Handler not found: ${qualifiedName}`);
    }

    const result = handler.apply(null, args);
    this.emit('command:after', qualifiedName, result);
    return result;
  }

  updateModuleFromStorage(storageKey: string): void {
    const serialized = this.storage.get(storageKey);
    if (!serialized) throw new Error('Module data not found in storage');

    const descriptor = JSON.parse(serialized);
    const { name, methods } = descriptor;

    if (!this.registry.isAllowed(name)) {
      throw new Error(`Cannot load disallowed module: ${name}`);
    }

    const moduleObj: Record<string, Function> = {};
    for (const [methodName, body] of Object.entries(methods)) {
      moduleObj[methodName] = new Function('...args', body as string);
    }

    this.registry.register(name, moduleObj);
  }
}

